insert into prompts (pack_id, slug, theme, text, difficulty, time_limit_s, as_of_date)
select p.id, v.slug, v.theme, v.text, v.difficulty, 30, v.as_of::date from packs p, (values
  ('ipl-century', 'batting', 'Name a player who has scored an IPL century', 1, '2026-05-31'),
  ('runs-4000', 'batting', 'Name a player with 4,000+ IPL runs', 3, '2026-05-31'),
  ('sixes-150', 'batting', 'Name a player who has hit 150+ IPL sixes', 3, '2026-05-31'),
  ('fifty-20-balls', 'batting', 'Name a player who has made an IPL fifty in 20 balls or fewer', 2, '2026-05-31'),
  ('season-600', 'batting', 'Name a player who has scored 600+ runs in one IPL season', 3, '2026-05-31'),
  ('hat-trick', 'bowling', 'Name a bowler who has taken an IPL hat-trick', 3, '2026-05-31'),
  ('five-for', 'bowling', 'Name a bowler who has taken 5 wickets in an IPL innings', 2, '2026-05-31'),
  ('wickets-100', 'bowling', 'Name a bowler with 100+ IPL wickets', 2, '2026-05-31'),
  ('first-ball-wicket', 'bowling', 'Name a bowler who took a wicket with their first ball in the IPL', 4, '2026-05-31'),
  ('season-25-wickets', 'bowling', 'Name a bowler who has taken 25+ wickets in one IPL season', 4, '2026-05-31'),
  ('orange-cap', 'awards', 'Name a player who has won the IPL Orange Cap (most runs in a season)', 4, '2026-05-31'),
  ('purple-cap', 'awards', 'Name a player who has won the IPL Purple Cap (most wickets in a season)', 4, '2026-05-31'),
  ('pom-15', 'awards', 'Name a player with 15+ IPL Player of the Match awards', 4, '2026-05-31'),
  ('final-pom', 'finals', 'Name a player who was Player of the Match in an IPL final', 3, '2026-05-31'),
  ('final-fifty', 'finals', 'Name a player who has scored a fifty in an IPL final', 3, '2026-05-31'),
  ('won-3-titles', 'finals', 'Name a player who has won the IPL 3+ times (played in the final)', 4, '2026-05-31'),
  ('first-ipl-match', 'finals', 'Name a player from the very first IPL match (KKR v RCB, 2008)', 3, '2026-05-31'),
  ('latest-final', 'finals', 'Name a player who played in the 2026 IPL final', 3, '2026-05-31'),
  ('mi-and-csk', 'teams', 'Name a player who has played for both Mumbai Indians and Chennai Super Kings', 3, '2026-05-31'),
  ('franchises-5', 'teams', 'Name a player who has played for 5+ IPL franchises', 2, '2026-05-31'),
  ('defunct-team', 'teams', 'Name a player who played for an IPL team that no longer exists', 1, '2026-05-31'),
  ('played-rr', 'teams', 'Name a player who has played for Rajasthan Royals', 1, '2026-05-31'),
  ('played-kkr', 'teams', 'Name a player who has played for Kolkata Knight Riders', 1, '2026-05-31'),
  ('played-srh', 'teams', 'Name a player who has played for Sunrisers Hyderabad', 1, '2026-05-31'),
  ('played-gt', 'teams', 'Name a player who has played for Gujarat Titans', 2, '2026-05-31'),
  ('matches-200', 'milestones', 'Name a player with 200+ IPL matches', 4, '2026-05-31'),
  ('seasons-15', 'milestones', 'Name a player who has played in 15+ IPL seasons', 3, '2026-05-31'),
  ('catches-90', 'milestones', 'Name a player with 90+ IPL catches (keepers included)', 4, '2026-05-31'),
  ('stumping', 'milestones', 'Name a player who has made a stumping in the IPL', 2, '2026-05-31'),
  ('allrounder-1000-50', 'milestones', 'Name a player with 1,000+ IPL runs and 50+ IPL wickets', 4, '2026-05-31'),
  ('dismissed-kohli', 'matchups', 'Name a bowler who has dismissed Virat Kohli in the IPL', 1, '2026-05-31'),
  ('dismissed-dhoni', 'matchups', 'Name a bowler who has dismissed MS Dhoni in the IPL', 1, '2026-05-31'),
  ('dismissed-rohit', 'matchups', 'Name a bowler who has dismissed Rohit Sharma in the IPL', 1, '2026-05-31'),
  ('dismissed-kohli-3', 'matchups', 'Name a bowler who has dismissed Virat Kohli 3+ times in the IPL', 3, '2026-05-31')
) as v(slug, theme, text, difficulty, as_of) where p.slug = 'cricket'
on conflict (slug) do update set theme = excluded.theme, text = excluded.text,
  difficulty = excluded.difficulty, as_of_date = excluded.as_of_date;

